# CODEFORGE DEEPSEEK REAL INTEGRATION PATCH 003
# Replaces the incomplete provider switch with a real DeepSeek integration.
# Run this script FROM the CodeForge backend folder.
# The script preserves your DEEPSEEK_API_KEY value; it never prints or overwrites it.

$ErrorActionPreference = "Stop"

$Backend = (Get-Location).Path
$Project = Split-Path $Backend -Parent
$Frontend = Join-Path $Project "frontend"
$PHP = "D:\xampp\php\php.exe"
$Stamp = Get-Date -Format "yyyyMMdd-HHmmss"

if (!(Test-Path $PHP)) {
    throw "XAMPP PHP was not found at $PHP"
}

$Service = Join-Path $Backend "app\Services\AiAssistantService.php"
$Config = Join-Path $Backend "config\ai_assistant.php"
$Controller = Join-Path $Backend "app\Http\Controllers\AiAssistantController.php"
$EnvFile = Join-Path $Backend ".env"
$FrontendAssistant = Join-Path $Frontend "src\lib\components\AIAssistant.svelte"

$Required = @($Service, $Config, $Controller, $EnvFile, $FrontendAssistant)
foreach ($File in $Required) {
    if (!(Test-Path $File)) {
        throw "Required file not found: $File"
    }
}

$Backups = @{}

function Backup-File([string]$Path) {
    $Backup = "$Path.backup-deepseek003-$Stamp"
    Copy-Item $Path $Backup -Force
    $script:Backups[$Path] = $Backup
    Write-Host "[BACKUP] $Backup"
}

function Restore-Backups {
    Write-Host "[ROLLBACK] Restoring changed files..."
    foreach ($Path in $script:Backups.Keys) {
        $Backup = $script:Backups[$Path]
        if (Test-Path $Backup) {
            Copy-Item $Backup $Path -Force
        }
    }
}

function Write-Base64File([string]$Path, [string]$Data) {
    $Bytes = [Convert]::FromBase64String($Data)
    [System.IO.File]::WriteAllBytes($Path, $Bytes)
}

function Read-Utf8([string]$Path) {
    return [System.IO.File]::ReadAllText($Path, [System.Text.Encoding]::UTF8)
}

function Write-Utf8NoBom([string]$Path, [string]$Text) {
    $Encoding = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText($Path, $Text, $Encoding)
}

function Set-EnvValue([string]$Text, [string]$Name, [string]$Value) {
    $Pattern = "(?m)^" + [regex]::Escape($Name) + "=.*$"
    $Replacement = "$Name=$Value"

    if ([regex]::IsMatch($Text, $Pattern)) {
        return [regex]::Replace($Text, $Pattern, $Replacement)
    }

    if (!$Text.EndsWith("`n")) {
        $Text += "`r`n"
    }

    return $Text + $Replacement + "`r`n"
}

try {
    Backup-File $Service
    Backup-File $Config
    Backup-File $Controller
    Backup-File $EnvFile
    Backup-File $FrontendAssistant

    # Write exact UTF-8 source files. Base64 avoids PowerShell encoding/BOM corruption.
    Write-Base64File $Service ""
    Write-Base64File $Config ""
    Write-Base64File $Controller ""
    Write-Base64File $FrontendAssistant ""

    Write-Host "[FIX] Installed real DeepSeek provider implementation"
    Write-Host "[FIX] Added Gemini fallback provider support"
    Write-Host "[FIX] Added coaching + coding-problem reasoning behavior"
    Write-Host "[FIX] Increased coding prompt limits and multi-line Copilot input"
    Write-Host "[FIX] Removed corrupted quote text from assistant service"

    # Update .env WITHOUT replacing the user's API key.
    $EnvText = Read-Utf8 $EnvFile

    if ($EnvText -notmatch "(?m)^DEEPSEEK_API_KEY=") {
        if (!$EnvText.EndsWith("`n")) {
            $EnvText += "`r`n"
        }
        $EnvText += "DEEPSEEK_API_KEY=`r`n"
    }

    $EnvText = Set-EnvValue $EnvText "CODEFORGE_AI_ENABLED" "true"
    $EnvText = Set-EnvValue $EnvText "CODEFORGE_AI_PROVIDER" "deepseek"
    $EnvText = Set-EnvValue $EnvText "CODEFORGE_AI_MODEL" "deepseek-flash"
    $EnvText = Set-EnvValue $EnvText "CODEFORGE_AI_FALLBACK_PROVIDER" "gemini"
    $EnvText = Set-EnvValue $EnvText "CODEFORGE_AI_FALLBACK_MODEL" "gemini-3.6-flash"
    $EnvText = Set-EnvValue $EnvText "CODEFORGE_AI_TIMEOUT" "35"

    Write-Utf8NoBom $EnvFile $EnvText
    Write-Host "[FIX] AI environment settings updated; DEEPSEEK_API_KEY preserved"

    # PHP syntax validation for changed PHP files only.
    foreach ($File in @($Service, $Config, $Controller)) {
        & $PHP -l $File
        if ($LASTEXITCODE -ne 0) {
            throw "PHP syntax validation failed: $File"
        }
    }

    # Clear Laravel caches so provider/model changes are actually loaded.
    Push-Location $Backend
    try {
        & $PHP artisan optimize:clear
        if ($LASTEXITCODE -ne 0) {
            throw "artisan optimize:clear failed"
        }
    } finally {
        Pop-Location
    }

    # Remove stale SvelteKit generated output so the new textarea/input limits are rebuilt.
    $SvelteCache = Join-Path $Frontend ".svelte-kit"
    $BuildDir = Join-Path $Frontend "build"

    if (Test-Path $SvelteCache) {
        Remove-Item $SvelteCache -Recurse -Force -ErrorAction SilentlyContinue
    }
    if (Test-Path $BuildDir) {
        Remove-Item $BuildDir -Recurse -Force -ErrorAction SilentlyContinue
    }

    $FinalEnv = Read-Utf8 $EnvFile
    $KeyMatch = [regex]::Match($FinalEnv, "(?m)^DEEPSEEK_API_KEY=(.*)$")
    $HasKey = $KeyMatch.Success -and ($KeyMatch.Groups[1].Value.Trim().Length -gt 0)

    Write-Host ""
    Write-Host "[SUCCESS] DeepSeek real integration patch completed."
    Write-Host "Primary provider: deepseek"
    Write-Host "Primary model: deepseek-flash"
    Write-Host "Fallback provider: gemini"
    Write-Host "DeepSeek key present: $HasKey"
    Write-Host ""
    Write-Host "Restart backend:"
    Write-Host "D:\xampp\php\php.exe artisan serve --host=127.0.0.1 --port=8000"
    Write-Host ""
    Write-Host "Restart frontend:"
    Write-Host "npm run dev -- --host 127.0.0.1"
}
catch {
    Write-Host "[ERROR] $($_.Exception.Message)"
    Restore-Backups
    Write-Host "[ROLLBACK] Original files restored."
    exit 1
}
